#!/usr/bin/env node
// scripts/make_fixtures.mjs - deterministic media fixtures for the browser e2e gates (M2, M5).
//
//   node scripts/make_fixtures.mjs [--out tests/fixtures/generated] [--require-mp4] [--only mp4|m5]
//
// Writes (all git-ignored, regenerated byte-for-byte from fixed seeds):
//   clip_240_h264.mp4   H.264 High, 1280x720, 240 fps, 300 frames: synthetic face_on scene (textured mat, resting ball,
//                       club arc, ball flight, distractor ball) from tests/synth/render.js. Needs an ffmpeg with libx264.
//   clip_240_vp9.mp4    same pictures, VP9 in MP4. Chromium builds without proprietary codecs (Playwright's) cannot decode
//                       H.264, so the M2 e2e test falls back to this file there (demux / timestamps / fps are the same).
//   clip_240.json       truth: { fps, sample_count, width, height, impact_frame_index, codecs: {...} }
//   m5_fake_cam.y4m     160x90 @ 10 fps, 105 s, for --use-file-for-fake-video-capture: a "wrist" marker that swings
//   m5_fake_mic.wav     44.1 kHz mono 16-bit, 105 s, for --use-file-for-fake-audio-capture: swish + impact clicks
//   m5_truth.json       { duration_s, events: [{ kind: 'real'|'practice'|'neighbor', t_start_s, t_impact_s }], counts }
//                       real = motion + swish + click (a detection), practice = motion + swish only,
//                       neighbor = click only (no motion).
//
// ffmpeg lookup: $FFMPEG, then PATH, then the imageio-ffmpeg binary inside the project venv ($GSL_PY, default
// ~/.local/share/golf-swing-lab-venv/bin/python). Without ffmpeg the y4m / wav / json files are still written, the MP4s
// are skipped with a warning (exit 0), or exit 1 with --require-mp4.

import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { spawn, spawnSync } from 'node:child_process';
import { fileURLToPath, pathToFileURL } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');

function mulberry32(a) {
  return () => {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export function findFfmpeg() {
  const cands = [];
  if (process.env.FFMPEG) cands.push(process.env.FFMPEG);
  const w = spawnSync('sh', ['-c', 'command -v ffmpeg'], { encoding: 'utf8' });
  if (w.status === 0 && w.stdout.trim()) cands.push(w.stdout.trim());
  const py = process.env.GSL_PY || path.join(os.homedir(), '.local/share/golf-swing-lab-venv/bin/python');
  if (fs.existsSync(py)) {
    const r = spawnSync(py, ['-I', '-c', 'import imageio_ffmpeg;print(imageio_ffmpeg.get_ffmpeg_exe())'], { encoding: 'utf8' });
    if (r.status === 0 && r.stdout.trim()) cands.push(r.stdout.trim());
  }
  for (const c of cands) {
    const r = spawnSync(c, ['-hide_banner', '-encoders'], { encoding: 'utf8' });
    if (r.status === 0 && /libx264/.test(r.stdout)) return { exe: c, vp9: /libvpx-vp9/.test(r.stdout) };
  }
  return null;
}

// ------------------------------------------------------------------------------------------------ MP4 clips

const CLIP = { seed: 20261104, nPre: 200, nPost: 100, W: 1280, H: 720, fps: 240 };

function encode(ff, frames, W, H, outFile, codecArgs) {
  return new Promise((resolve, reject) => {
    const args = ['-hide_banner', '-loglevel', 'error', '-y', '-f', 'rawvideo', '-pix_fmt', 'gray', '-s', `${W}x${H}`, '-r', String(CLIP.fps), '-i', '-',
      '-vf', `scale=${CLIP.W}:${CLIP.H}:flags=bicubic,format=yuv420p`, '-r', String(CLIP.fps), ...codecArgs,
      '-an', '-map_metadata', '-1', '-fflags', '+bitexact', '-flags:v', '+bitexact', '-video_track_timescale', '240000', '-movflags', '+faststart', outFile];
    const p = spawn(ff.exe, args, { stdio: ['pipe', 'inherit', 'inherit'] });
    p.on('error', reject);
    p.on('close', (code) => (code === 0 ? resolve() : reject(new Error(`ffmpeg exited ${code}`))));
    let i = 0;
    const pump = () => {
      while (i < frames.length) {
        if (!p.stdin.write(Buffer.from(frames[i].buffer, frames[i].byteOffset, frames[i].byteLength))) {
          i++;
          p.stdin.once('drain', pump);
          return;
        }
        i++;
      }
      p.stdin.end();
    };
    p.stdin.on('error', () => {});
    pump();
  });
}

async function makeClips(outDir, ff) {
  const { makeShotSpec, renderClip } = await import(pathToFileURL(path.join(root, 'tests/synth/render.js')).href);
  const spec = makeShotSpec(CLIP.seed, { nPre: CLIP.nPre, nPost: CLIP.nPost });
  const clip = renderClip(spec);
  const n = clip.frames.length;
  const files = {};
  await encode(ff, clip.frames, clip.W, clip.H, path.join(outDir, 'clip_240_h264.mp4'),
    ['-c:v', 'libx264', '-profile:v', 'high', '-preset', 'medium', '-crf', '18', '-g', '60', '-threads', '1', '-x264-params', 'threads=1:bframes=2', '-tag:v', 'avc1']);
  files.h264 = 'clip_240_h264.mp4';
  if (ff.vp9) {
    await encode(ff, clip.frames, clip.W, clip.H, path.join(outDir, 'clip_240_vp9.mp4'),
      ['-c:v', 'libvpx-vp9', '-crf', '30', '-b:v', '0', '-g', '60', '-row-mt', '0', '-threads', '1', '-deadline', 'good', '-cpu-used', '4']);
    files.vp9 = 'clip_240_vp9.mp4';
  }
  const truth = {
    fps: CLIP.fps, sample_count: n, width: CLIP.W, height: CLIP.H, duration_s: n / CLIP.fps,
    impact_frame_index: spec.meta.tImp, seed: CLIP.seed, files,
    codecs: { h264: 'avc1.64002A', vp9: 'vp09.00.40.08' },
  };
  fs.writeFileSync(path.join(outDir, 'clip_240.json'), JSON.stringify(truth, null, 2) + '\n');
  return truth;
}

// ------------------------------------------------------------------------------------------------ M5 media

// rate 48000 = the AudioContext rate of headless Chromium: a 44100 Hz wav goes through the fake capture device's
// resampler, which ran 0.03-0.22 % slow run to run (up to 0.23 s late after 100 s, beyond events/live.js's +-0.3 s
// audio-fusion window together with the 0.06 s base offset) - the m5 flakiness of 2026-11-04. At 48000 the drift is
// <= 0.014 %.
// fps 30: the live loop samples 10 Hz idle and 30 Hz inside a swing (frame tap setFps); a 10 fps camera starved the
// SWING-state sampling, quantising the wrist-speed peak that the audio click must fall within +-0.3 s of to 0.1 s, so
// one late frame under CPU load could turn a real swing into "practice".
export const M5 = { seed: 5150, w: 160, h: 90, fps: 30, rate: 48000, lead_s: 3, slot_s: 4, tail_s: 2, real: 10, practice: 5, neighbor: 10 };

export function m5Timeline() {
  const rng = mulberry32(M5.seed);
  const kinds = [...Array(M5.real).fill('real'), ...Array(M5.practice).fill('practice'), ...Array(M5.neighbor).fill('neighbor')];
  for (let i = kinds.length - 1; i > 0; i--) {
    const j = Math.floor(rng() * (i + 1));
    [kinds[i], kinds[j]] = [kinds[j], kinds[i]];
  }
  const events = kinds.map((kind, i) => {
    const t0 = M5.lead_s + i * M5.slot_s;
    return { kind, t_start_s: t0, t_impact_s: t0 + 1.2 };
  });
  const duration_s = M5.lead_s + kinds.length * M5.slot_s + M5.tail_s;
  return { duration_s, events, counts: { real: M5.real, practice: M5.practice, neighbor: M5.neighbor } };
}

const smooth = (x) => { const t = Math.min(1, Math.max(0, x)); return t * t * (3 - 2 * t); };
const lerp = (a, b, t) => a + (b - a) * t;

// Wrist marker position in [0,1]^2 (x right, y down) at local time s (seconds since the event slot start).
function wrist(s) {
  const A = [0.5, 0.7], T = [0.35, 0.2], F = [0.65, 0.25];
  if (s < 0) return A;
  if (s < 0.9) { const t = smooth(s / 0.9); return [lerp(A[0], T[0], t), lerp(A[1], T[1], t)]; }
  if (s < 1.2) { const t = (s - 0.9) / 0.3; return [lerp(T[0], A[0], t), lerp(T[1], A[1], t * t)]; }
  if (s < 1.7) { const t = smooth((s - 1.2) / 0.5); return [lerp(A[0], F[0], t), lerp(A[1], F[1], t)]; }
  if (s < 2.4) return F;
  if (s < 3.4) { const t = smooth((s - 2.4) / 1.0); return [lerp(F[0], A[0], t), lerp(F[1], A[1], t)]; }
  return A;
}

// Frame-index code (gate m5 maps the frame tap's media time to fixture time with it; 12 bits >= 3150 frames): FRAME_CODE.bits cells of
// FRAME_CODE.cell px along the top edge, bit k (LSB first) of the frame index, then one even-parity cell; on = luma
// FRAME_CODE.on (below the stand-in's disc threshold 180, far above the background 64-99). The disc never comes
// within 11 px of the top edge (y >= 0.2 h - 7), so the code does not move the disc centroid.
export const FRAME_CODE = Object.freeze({ id: 'gsl-framecode/1', bits: 12, x0: 2, cell: 6, rows: 6, on: 160 });

function drawFrameCode(Y, w, n) {
  const { bits, x0, cell, rows, on } = FRAME_CODE;
  let par = 0;
  for (let k = 0; k <= bits; k++) {
    let b;
    if (k < bits) { b = (n >> k) & 1; par ^= b; } else b = par;
    if (!b) continue;
    for (let y = 0; y < rows; y++) for (let x = x0 + k * cell; x < x0 + (k + 1) * cell; x++) Y[y * w + x] = on;
  }
}

function writeY4m(file, tl) {
  const { w, h, fps } = M5;
  const n = Math.round(tl.duration_s * fps);
  const fd = fs.openSync(file, 'w');
  fs.writeSync(fd, `YUV4MPEG2 W${w} H${h} F${fps}:1 Ip A1:1 C420jpeg\n`);
  const rng = mulberry32(M5.seed + 1);
  const bg = new Uint8Array(w * h);
  for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) bg[y * w + x] = 70 + Math.round(20 * (y / h) + 6 * Math.sin(x / 9) + rng() * 3);
  const Y = new Uint8Array(w * h);
  const cw = w / 2, ch = h / 2;
  const UV = new Uint8Array(cw * ch * 2).fill(128);
  for (let f = 0; f < n; f++) {
    const t = f / fps;
    let pos = [0.5, 0.7];
    for (const e of tl.events) {
      if (e.kind === 'neighbor') continue;
      const s = t - e.t_start_s;
      if (s >= 0 && s < M5.slot_s) { pos = wrist(s); break; }
    }
    Y.set(bg);
    const cx = pos[0] * w, cy = pos[1] * h, r = 6;
    for (let y = Math.max(0, Math.floor(cy - r - 1)); y <= Math.min(h - 1, Math.ceil(cy + r + 1)); y++) {
      for (let x = Math.max(0, Math.floor(cx - r - 1)); x <= Math.min(w - 1, Math.ceil(cx + r + 1)); x++) {
        const d = Math.hypot(x + 0.5 - cx, y + 0.5 - cy);
        if (d <= r) Y[y * w + x] = 235;
        else if (d <= r + 1) Y[y * w + x] = Math.round(lerp(235, Y[y * w + x], d - r));
      }
    }
    drawFrameCode(Y, w, f);
    fs.writeSync(fd, 'FRAME\n');
    fs.writeSync(fd, Y);
    fs.writeSync(fd, UV.subarray(0, cw * ch)); // U then V, both flat 128
    fs.writeSync(fd, UV.subarray(0, cw * ch));
  }
  fs.closeSync(fd);
  return n;
}

function writeWav(file, tl) {
  const sr = M5.rate;
  const n = Math.round(tl.duration_s * sr);
  const x = new Float32Array(n);
  const rng = mulberry32(M5.seed + 2);
  // room noise floor
  for (let i = 0; i < n; i++) x[i] = (rng() * 2 - 1) * 0.004;
  let lp = 0;
  const swish = (t0, dur, amp) => {
    const i0 = Math.round(t0 * sr), len = Math.round(dur * sr);
    for (let i = 0; i < len && i0 + i < n; i++) {
      const env = Math.sin((Math.PI * i) / len) ** 2;
      lp += 0.35 * ((rng() * 2 - 1) - lp); // gentle low-pass: whoosh, not click
      x[i0 + i] += lp * env * amp;
    }
  };
  const click = (t0, amp) => {
    const i0 = Math.round(t0 * sr);
    for (let i = 0; i < Math.round(0.12 * sr) && i0 + i < n; i++) {
      const t = i / sr;
      x[i0 + i] += amp * Math.exp(-t / 0.012) * (0.6 * Math.sin(2 * Math.PI * 3200 * t) + 0.4 * (rng() * 2 - 1));
    }
  };
  for (const e of tl.events) {
    if (e.kind !== 'neighbor') swish(e.t_impact_s - 0.45, 0.45, 0.12);
    if (e.kind !== 'practice') click(e.t_impact_s, e.kind === 'real' ? 0.8 : 0.7);
  }
  const buf = Buffer.alloc(44 + n * 2);
  buf.write('RIFF', 0); buf.writeUInt32LE(36 + n * 2, 4); buf.write('WAVE', 8); buf.write('fmt ', 12);
  buf.writeUInt32LE(16, 16); buf.writeUInt16LE(1, 20); buf.writeUInt16LE(1, 22); buf.writeUInt32LE(sr, 24);
  buf.writeUInt32LE(sr * 2, 28); buf.writeUInt16LE(2, 32); buf.writeUInt16LE(16, 34); buf.write('data', 36); buf.writeUInt32LE(n * 2, 40);
  for (let i = 0; i < n; i++) buf.writeInt16LE(Math.max(-32767, Math.min(32767, Math.round(x[i] * 32767))), 44 + i * 2);
  fs.writeFileSync(file, buf);
  return n;
}

function makeM5(outDir) {
  const tl = m5Timeline();
  const frames = writeY4m(path.join(outDir, 'm5_fake_cam.y4m'), tl);
  const samples = writeWav(path.join(outDir, 'm5_fake_mic.wav'), tl);
  fs.writeFileSync(path.join(outDir, 'm5_truth.json'), JSON.stringify({ ...tl, video: { w: M5.w, h: M5.h, fps: M5.fps, frames, frame_code: FRAME_CODE }, audio: { rate: M5.rate, samples } }, null, 2) + '\n');
  return tl;
}

// ------------------------------------------------------------------------------------------------ main

async function main(argv) {
  let out = path.join(root, 'tests/fixtures/generated');
  let only = null;
  let requireMp4 = false;
  for (let i = 2; i < argv.length; i++) {
    if (argv[i] === '--out' && argv[i + 1]) out = path.resolve(argv[++i]);
    else if (argv[i] === '--only' && argv[i + 1]) only = argv[++i];
    else if (argv[i] === '--require-mp4') requireMp4 = true;
    else { console.error('usage: make_fixtures.mjs [--out dir] [--require-mp4] [--only mp4|m5]'); return 64; }
  }
  fs.mkdirSync(out, { recursive: true });
  let rc = 0;
  if (only !== 'mp4') {
    const tl = makeM5(out);
    console.log(`m5: ${tl.events.length} events, ${tl.duration_s}s -> m5_fake_cam.y4m m5_fake_mic.wav m5_truth.json`);
  }
  if (only !== 'm5') {
    const ff = findFfmpeg();
    if (!ff) {
      console.warn('WARNING: no ffmpeg with libx264 found (set FFMPEG=, or install ffmpeg); clip_240_*.mp4 NOT generated, M2 e2e will be skipped');
      rc = requireMp4 ? 1 : 0;
    } else {
      const t = await makeClips(out, ff);
      console.log(`mp4: ${t.sample_count} frames @ ${t.fps} fps -> ${Object.values(t.files).join(' ')} (${ff.exe})`);
    }
  }
  return rc;
}

if (process.argv[1] && fileURLToPath(import.meta.url) === path.resolve(process.argv[1])) {
  main(process.argv).then((c) => { process.exitCode = c; }, (e) => { console.error(e); process.exitCode = 1; });
}
